/**
 * 角色图鉴本地生平历程 (passages) 兜底数据
 *
 * 当远程 passages 为空时，使用本数据提供生平时间线。
 * 按人物分组，每个 passage 包含时间、地点、标题、内容、出处。
 * 同时记录关联人物ID，用于思维导图跳转。
 */
import type { MainFigurePassage } from "../../services/mainProjectApi";

export interface PassageWithRelations extends MainFigurePassage {
	related_ids?: string[]; // 关联人物ID，思维导图连线用
	event_group?: string; // 事件分组（如同一场战役）
}

function mk(
	id: string,
	pid: string,
	ch: string,
	chname: string,
	v: number,
	title: string,
	content: string,
	year: number | null,
	loc: string | null,
	idx: number,
	related: string[] = [],
	group?: string,
): PassageWithRelations {
	return {
		passage_id: pid,
		chapter_id: ch,
		chapter_name: chname,
		book_id: "shiji",
		book_name: "史记",
		volume_no: v,
		title,
		content,
		year,
		location: loc,
		order_idx: idx,
		related_ids: related,
		event_group: group,
	};
}

